def allMetadata[T](raster: RDD[ITile[T]]): Array[RasterMetadata] =
    // For efficiency, we assume that all metadata in each partition is the same
    raster.mapPartitions(tiles => {
        if (tiles.hasNext) {
          Some(tiles.next().rasterMetadata).iterator
        } else {
          Option.empty[RasterMetadata].iterator
        }
      }).distinct()
      .collect()

def flatten[T](raster: RasterRDD[T]): RDD[(Int, Int, RasterMetadata, T)] = {
    raster.flatMap(tile => {
      for (y <- tile.y1 to tile.y2 iterator; x <- tile.x1 to tile.x2 iterator; if tile.isDefined(x, y))
        yield (x, y, tile.rasterMetadata, tile.getPixelValue(x, y))
    })
  }

