def raptorJoinFeature[T](raster: RasterRDD[T], features: RDD[IFeature], opts: BeastOptions = new BeastOptions(),
                           numTiles: LongAccumulator = null): RDD[RaptorJoinFeature[T]] = {
    val featureIDs: RDD[(Long, IFeature)] = features.zipWithUniqueId().map(x => (x._2, x._1))
    val joinResults = raptorJoinIDFull[T](raster, featureIDs, opts, numTiles)
      .map(x => (x.featureID, x))
    val partitioner = new HashPartitioner(joinResults.getNumPartitions max featureIDs.getNumPartitions max featureIDs.sparkContext.defaultParallelism)
    featureIDs.partitionBy(partitioner)
      .zipPartitions(joinResults.partitionBy(partitioner))((fs, rjs) => {
      val fsMap = fs.toMap
      rjs.map(rj => {
        RaptorJoinFeature(fsMap(rj._1), rj._2.rasterMetadata, rj._2.x, rj._2.y, rj._2.m)
      })
    })
  }

def reproject[T: ClassTag](raster: RasterRDD[T], targetCRS: CoordinateReferenceSystem, unifiedRaster: Boolean = false,
                             interpolationMethod: InterpolationMethod.InterpolationMethod =
                             InterpolationMethod.NearestNeighbor): RasterRDD[T] = {
    val targetMetadata: RasterMetadata => RasterMetadata = if (!unifiedRaster) {
      _.reproject(targetCRS)
    } else {
      val unifiedMetadata = RasterMetadata.reproject(RasterMetadata.allMetadata(raster), targetCRS)
      logInfo(s"Reprojecting with unified metadata ${unifiedMetadata}")
      _ => unifiedMetadata
    }
    interpolationMethod match {
      case InterpolationMethod.Average => reshapeAverage(raster, targetMetadata)
      case InterpolationMethod.NearestNeighbor => reshapeNN(raster, targetMetadata)
    }
  }

def rescale[T: ClassTag](raster: RasterRDD[T], rasterWidth: Int, rasterHeight: Int, unifiedRaster: Boolean = false,
                           interpolationMethod: InterpolationMethod.InterpolationMethod =
                           InterpolationMethod.NearestNeighbor): RasterRDD[T] = {
    val targetMetadata: RasterMetadata => RasterMetadata = if (!unifiedRaster) {
      _.rescale(rasterWidth, rasterHeight)
    } else {
      val unifiedMetadata = RasterMetadata.rescale(RasterMetadata.allMetadata(raster), rasterWidth, rasterHeight)
      logInfo(s"Rescaling with unified metadata ${unifiedMetadata}")
      _ =>  unifiedMetadata
    }
    interpolationMethod match {
      case InterpolationMethod.Average => reshapeAverage(raster, targetMetadata)
      case InterpolationMethod.NearestNeighbor => reshapeNN(raster, targetMetadata)
    }
  }

def retile[T: ClassTag](raster: RasterRDD[T], tileWidth: Int, tileHeight: Int): RasterRDD[T] = {
    // Notice that for retile, there is a one-to-one correspondence in pixels so we use the more efficient NN method
    reshapeNN(raster, _.retile(tileWidth, tileHeight))
  }

def saveAsGeoTiff[T](rasterRDD: RDD[ITile[T]], outPath: String, opts: BeastOptions): Unit = {
    def maxArrayB(a: Array[Byte], b: Array[Byte]): Array[Byte] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    def maxArrayS(a: Array[Short], b: Array[Short]): Array[Short] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    def maxArrayI(a: Array[Int], b: Array[Int]): Array[Int] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    def maxArrayL(a: Array[Long], b: Array[Long]): Array[Long] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    if (!opts.contains(BitsPerSample) && opts.getBoolean(CompactBits, false)) {
      // Automatically compute bits per sample based on the maximum value
      val pixelType = rasterRDD.first().pixelType
      val measures = RasterOperationsGlobal.flatten(rasterRDD)
      val max: Array[Long] = pixelType match {
        case ByteType =>
          Array(measures.map(_._4.asInstanceOf[Byte]).reduce(_ max _))
        case ShortType =>
          Array(measures.map(_._4.asInstanceOf[Short]).reduce(_ max _))
        case IntegerType =>
          Array(measures.map(_._4.asInstanceOf[Int]).reduce(_ max _))
        case LongType =>
          Array(measures.map(_._4.asInstanceOf[Long]).reduce(_ max _))
        case ArrayType(ByteType, _) =>
          measures.map(_._4.asInstanceOf[Array[Byte]]).reduce(maxArrayB).map(_.toLong)
        case ArrayType(ShortType, _) =>
          measures.map(_._4.asInstanceOf[Array[Short]]).reduce(maxArrayS).map(_.toLong)
        case ArrayType(IntegerType, _) =>
          measures.map(_._4.asInstanceOf[Array[Int]]).reduce(maxArrayI).map(_.toLong)
        case ArrayType(LongType, _) =>
          measures.map(_._4.asInstanceOf[Array[Long]]).reduce(maxArrayL).map(_.toLong)
        case _ => null // Float types will not need a maximum value
      }
      if (max != null) {
        val bitsPerSample = max.map(x => MathUtil.log2(x + 1))
        opts.set(BitsPerSample, bitsPerSample.mkString(","))
        opts.set(FillValue, max.max + 1)
      }
    }
    opts.getString(WriteMode, "distributed") match {
      case "distributed" => saveAsGeoTiffDistributedMode(rasterRDD, outPath, opts)
      case "compatibility" => saveAsGeoTiffCompatibilityMode(rasterRDD, outPath, opts)
    }
  }

def rasterizePixels[T: ClassTag](pixels: RDD[(Int, Int, T)], metadata: RasterMetadata, rasterFeature: RasterFeature): RasterRDD[T] = {
    val pixelsAssignedToTiles: RDD[(Int, (Int, Int, T))] = pixels.map(p => {
      val tileID = metadata.getTileIDAtPixel(p._1, p._2)
      (tileID, p)
    })
    pixelsAssignedToTiles.groupByKey().map(t => {
      val tile = new MemoryTile[T](t._1, metadata, rasterFeature)
      for (p <- t._2)
        tile.setPixelValue(p._1, p._2, p._3)
      tile
    })
  }

def rasterizePoints[T: ClassTag](points: RDD[(Double, Double, T)], metadata: RasterMetadata, rasterFeature: RasterFeature): RasterRDD[T] = {
    rasterizePixels(points.map(p => {
      val geolocation = Array(p._1, p._2)
      metadata.g2m.inverseTransform(geolocation, 0, geolocation, 0, 1)
      (geolocation(0).toInt, geolocation(1).toInt, p._3)
    }), metadata, rasterFeature)
  }

def getTileX1(tileID: Int): Int = {
    val iTile = tileID % numTilesX
    x1 + iTile * tileWidth
  }

def getTileX2(tileID: Int): Int = {
    val iTile = tileID % numTilesX
    (x1 + (iTile + 1) * tileWidth - 1) min (x2 - 1)
  }

def getTileY1(tileID: Int): Int = {
    val iTile = tileID / numTilesX
    y1 + iTile * tileHeight
  }

def getTileY2(tileID: Int): Int = {
    val iTile = tileID / numTilesX
    (y1 + (iTile + 1) * tileHeight - 1) min (y2 - 1)
  }
